import axios from 'axios';

// Empty for now as requested.
// This will be used to connect to the Flask backend later.
const api = axios.create({
  baseURL: 'http://127.0.0.1:5000/api', // Example URL
});

export const reanalysePatient = async (id) => {
  const response = await fetch(`http://127.0.0.1:5000/api/patients/${id}/reanalyse`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
  });
  if (!response.ok) {
    throw new Error('Failed to re-analyse patient');
  }
  return await response.json();
};

export default api;
